    private const string Token="kiwi-media://";
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(new StringName(key),out var value)?value:fallback;
    private static bool AudioPath(string path)=>path.GetExtension().ToLowerInvariant() is "wav" or "mp3" or "ogg" or "flac";
    private static bool Cancelled(RefCounted? work)=>work!=null&&work.Call("is_cancelled").AsBool();
    private static CSharpScript DocumentScript()=>GD.Load<CSharpScript>("res://Workspaces/AudioWorkspace/KiwiAudioDocument.cs");
    private static string Kind(Resource resource)=>DocumentScript().Call("_recovery_kind",resource).AsString();
    private static Resource? NewResource(string kind)=>DocumentScript().Call("_new_recovery_resource",kind).As<Resource>();
    private static RefCounted NewScan()=>DocumentScript().Call("_new_portable_scan").As<RefCounted>();
    private static Settings Error(string error)=>new Settings{["error"]=error};
    public Settings freeze(Resource? document){using var recovery=new AudioRecoveryOperations();var result=recovery.freeze(document);if(Get(result,"error","").AsString().Length>0)result["error"]="Portable copy cannot freeze this metadata: "+result["error"].AsString();return result;}
    public bool is_cancelled(RefCounted? work)=>Cancelled(work);
