            using var hash=System.Security.Cryptography.IncrementalHash.CreateHash(System.Security.Cryptography.HashAlgorithmName.SHA256);long remaining=expected["bytes"].AsInt64();string problem="";
            while(remaining>0){if(Cancelled(work)){problem="Portable copy cancelled.";break;}int amount=(int)Math.Min(65536,remaining);var bytes=input.GetBuffer(amount);if(bytes.Length!=amount){problem="Source became unreadable while copying: "+path;break;}hash.AppendData(bytes);if(output!=null){output.StoreBuffer(bytes);if(output.GetError()!=Godot.Error.Ok){problem="Could not finish writing copied media. Check free disk space.";break;}}remaining-=amount;}
