    }
    public void fail(RefCounted o,string message){if(o.Get("_error").AsString().Length==0)o.Set("_error",message);}
    public void reference(RefCounted o,Variant container,Variant key,Variant value,string label)
    {
        if(value.VariantType==Variant.Type.Nil||(value.VariantType==Variant.Type.String&&value.AsString().Length==0))return;var references=o.Get("_references").AsGodotArray();if(value.VariantType==Variant.Type.String){references.Add(new Settings{["container"]=container,["key"]=key,["value"]=value,["label"]=label});return;}
        if(value.VariantType!=Variant.Type.Object||value.AsGodotObject() is not AudioStream audio||audio.GetScript().AsGodotObject()!=null||audio is not AudioStreamWav and not AudioStreamMP3){fail(o,"Unsupported media reference at "+label+". Only file WAV/MP3/Ogg/FLAC and unscripted embedded WAV/MP3 are portable.");return;}ulong id=audio.GetInstanceId();references.Add(new Settings{["container"]=container,["key"]=key,["value"]=value,["label"]=label});var streams=o.Get("_streams").AsGodotDictionary();if(streams.TryGetValue(id,out var old)){var state=old.AsGodotDictionary();state["references"]=state["references"].AsInt64()+1;return;}if(streams.Count>=2048){fail(o,"Embedded audio exceeds the 2048-source count limit.");return;}double seconds=audio.GetLength();if(!double.IsFinite(seconds)||seconds<=0){fail(o,"Embedded audio has an invalid or empty duration at "+label);return;}double estimate;
        if(audio is AudioStreamWav wav){if(wav.MixRate<1||wav.MixRate>384000){fail(o,"Embedded WAV has an unsupported sample rate.");return;}estimate=Math.Ceiling(seconds*wav.MixRate)*(wav.Stereo?2:1)*4+4096;}else estimate=Math.Ceiling(seconds*128000)+1024*1024;if(!double.IsFinite(estimate)||estimate>64L*1024*1024){fail(o,"An embedded source exceeds the conservative 64 MiB portable-save limit. Export it to an audio file first.");return;}long total=o.Get("_embedded_bytes").AsInt64()+(long)estimate;o.Set("_embedded_bytes",total);if(total>128L*1024*1024){fail(o,"Embedded audio exceeds the conservative 128 MiB portable-save budget. Export large sources to files first.");return;}streams[id]=new Settings{["kind"]="embedded",["source"]="Embedded "+(audio is AudioStreamWav?"WAV":"MP3"),["label"]=label,["bytes"]=(long)estimate,["references"]=1,["status"]="ready",["sha256"]="",["stream"]=audio};
    }
    public void walk(RefCounted o,Variant value,string label,int depth)
    {
        long visits=o.Get("_visits").AsInt64()+1;o.Set("_visits",visits);if(depth>32||visits>100000){fail(o,"Portable metadata exceeds the depth or entry budget.");return;}if(o.Get("_error").AsString().Length>0)return;
        if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is AudioStream){fail(o,"Audio resource appears outside a supported media field at "+label);return;}
        if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource resource)
        {
            string kind=Kind(resource);var blank=NewResource(kind);if(blank==null||resource.GetScript().AsGodotObject()!=blank.GetScript().AsGodotObject()){fail(o,"Unsupported resource schema at "+label);return;}if(kind=="reference"&&resource.Get("source").AsInt64()==1){fail(o,"A project asset-ID reference cannot be made portable. Embed or remove that reference first.");return;}ulong id=resource.GetInstanceId();var active=o.Get("_active").AsGodotDictionary();var seen=o.Get("_seen").AsGodotDictionary();if(active.ContainsKey(id)){fail(o,"Cyclic resource metadata is unsupported.");return;}if(seen.ContainsKey(id))return;seen[id]=true;active[id]=true;using var recovery=new AudioRecoveryOperations();foreach(string field in recovery.properties(resource)){if(kind=="document"&&field is "portable_media" or "output_path" or "scene_binding")continue;walk(o,resource.Get(field),label+"."+field,depth+1);}active.Remove(id);
        }
        else if(value.VariantType==Variant.Type.Dictionary)
        {
            var source=value.AsGodotDictionary();foreach(var key in source.Keys){if(key.VariantType is Variant.Type.Object or Variant.Type.Array or Variant.Type.Dictionary){fail(o,"Unsupported metadata dictionary key.");return;}string name=key.AsString();var item=source[key];if(name is "audio" or "original_audio" or "sample" or "impulse" or "impulse_path")reference(o,value,key,item,label+"."+name);else if(item.VariantType==Variant.Type.String&&item.AsString().Length>0&&(name is "path" or "file" or "source"||name.EndsWith("_path",StringComparison.Ordinal)||name.EndsWith("_file",StringComparison.Ordinal)))fail(o,"Unrecognized file-reference field at "+label+"."+name+". Portable copy will not guess its schema.");else walk(o,item,label+"."+name,depth+1);}
        }
        else if(value.VariantType==Variant.Type.Array){var items=value.AsGodotArray();for(int i=0;i<items.Count;++i)walk(o,items[i],label+"["+i+"]",depth+1);}
        else if(value.VariantType==Variant.Type.PackedStringArray){var items=value.AsStringArray();for(int i=0;i<items.Length;++i)walk(o,items[i],label+"["+i+"]",depth+1);}
        else if(value.VariantType is Variant.Type.String or Variant.Type.StringName){string text=value.AsString();if(text.StartsWith(Token,StringComparison.Ordinal)||text.StartsWith("res://",StringComparison.Ordinal)||text.StartsWith("user://",StringComparison.Ordinal)||text.IsAbsolutePath()||(AudioPath(text)&&text.Contains('/')))fail(o,"Unrecognized path-bearing metadata at "+label+". Portable copy will not guess its schema.");}
        else if(value.VariantType is Variant.Type.Object or Variant.Type.Callable or Variant.Type.Signal or Variant.Type.Rid)fail(o,"Unsupported live metadata at "+label);
    }
    public string manifest_error(Settings manifest)
    {
        if(manifest.Count!=2||Get(manifest,"version").VariantType!=Variant.Type.Int||manifest["version"].AsInt64()!=1||Get(manifest,"assets").VariantType!=Variant.Type.Array)return "Unsupported or corrupt portable media manifest.";var assets=manifest["assets"].AsGodotArray();if(assets.Count>2048)return "Portable media manifest exceeds the file-count limit.";var ids=new System.Collections.Generic.HashSet<string>();long total=0;using var recovery=new AudioRecoveryOperations();foreach(var raw in assets){if(raw.VariantType!=Variant.Type.Dictionary||raw.AsGodotDictionary().Count!=4)return "Invalid portable media manifest entry.";var entry=raw.AsGodotDictionary();if(Get(entry,"id").VariantType!=Variant.Type.String||Get(entry,"path").VariantType!=Variant.Type.String||Get(entry,"sha256").VariantType!=Variant.Type.String||Get(entry,"bytes").VariantType!=Variant.Type.Int)return "Invalid portable media manifest field type.";string id=entry["id"].AsString(),extension=id.GetExtension();if(extension is not "wav" and not "mp3" and not "ogg" and not "flac"||id!=entry["sha256"].AsString()+"."+extension||!recovery.hex(entry["sha256"].AsString(),64))return "Invalid portable media identity.";long bytes=entry["bytes"].AsInt64();if(entry["path"].AsString()!="media/"+id||!ids.Add(id)||bytes<=0||bytes>512L*1024*1024)return "Unsafe, duplicate, or oversized portable media path.";total+=bytes;if(total>2L*1024*1024*1024)return "Portable media exceeds the 2 GiB copy budget.";}return "";
    }
    public Settings manifest_map(Settings manifest){var result=new Settings();foreach(var raw in Get(manifest,"assets",new GArray()).AsGodotArray()){var entry=raw.AsGodotDictionary();result[entry["id"].AsString()]=entry;}return result;}
    public string inside_state(string root,string relative){using var parent=DirAccess.Open(root);if(parent==null)return "missing";if(parent.IsLink("media"))return "blocked";if(!parent.DirExists("media"))return "missing";using var media=DirAccess.Open(root.PathJoin("media"));if(media==null)return "missing";string name=relative.GetFile();if(media.IsLink(name))return "blocked";return media.FileExists(name)?"ready":"missing";}
    public string reference_id(string value,Settings entries,string root){if(value.StartsWith(Token,StringComparison.Ordinal)){string id=value[Token.Length..];return entries.ContainsKey(id)?id:"";}string path=canonical(value);if(root.Length==0||path.Length==0)return "";string name=path.GetFile();return entries.TryGetValue(name,out var entry)&&path==root.PathJoin(entry.AsGodotDictionary()["path"].AsString())?name:"";}
    public string infer_root(GArray references,Settings entries){string root="";foreach(var raw in references){var reference=raw.AsGodotDictionary();var value=reference["value"];if(value.VariantType!=Variant.Type.String||value.AsString().StartsWith(Token,StringComparison.Ordinal))continue;string path=canonical(value.AsString()),id=path.GetFile();if(path.Length==0||!entries.ContainsKey(id)||path.GetBaseDir().GetFile()!="media")continue;string candidate=path.GetBaseDir().GetBaseDir();if(root.Length>0&&candidate!=root)return "";root=candidate;}return root;}
    public void embed_streams(GArray references){var clones=new Settings();foreach(var raw in references){var reference=raw.AsGodotDictionary();if(reference["value"].VariantType!=Variant.Type.Object||reference["value"].AsGodotObject() is not AudioStream audio)continue;ulong id=audio.GetInstanceId();if(!clones.ContainsKey(id)){Resource clone=audio;if(clone.ResourcePath.Length>0){clone=clone.Duplicate(false);clone.ResourcePath="";}clones[id]=clone;}reference["container"].AsGodotDictionary()[reference["key"]]=clones[id];}}
}
